-- Spec 281 T5: o boleto por WhatsApp (Evolution) ao cliente, no trilho de entrega da 248/279. Aditiva: alvo, motivos e o
-- id da mensagem no provedor (nulo em toda linha existente); nenhuma linha muda.
ALTER TABLE "occurrence_contractor_reply_deliveries" ADD COLUMN "provider_message_id" text;--> statement-breakpoint
CREATE UNIQUE INDEX "occurrence_contractor_reply_deliveries_provider_message_unique" ON "occurrence_contractor_reply_deliveries" ("company_id","provider_message_id") WHERE "provider_message_id" is not null;--> statement-breakpoint
ALTER TABLE "occurrence_contractor_reply_deliveries" ADD CONSTRAINT "occurrence_contractor_reply_deliveries_provider_message_check" CHECK ("provider_message_id" is null or ("target" = 'client_boleto_whatsapp' and char_length("provider_message_id") between 1 and 200));--> statement-breakpoint
ALTER TABLE "occurrence_contractor_reply_deliveries" DROP CONSTRAINT "occurrence_contractor_reply_deliveries_target_check", ADD CONSTRAINT "occurrence_contractor_reply_deliveries_target_check" CHECK ("target" in ('driver_app_chat', 'driver_whatsapp', 'note_recipient_email', 'informed_email', 'contractor_acknowledgement', 'client_boleto_emails', 'client_boleto_whatsapp'));--> statement-breakpoint
ALTER TABLE "occurrence_contractor_reply_deliveries" DROP CONSTRAINT "occurrence_contractor_reply_deliveries_reason_check", ADD CONSTRAINT "occurrence_contractor_reply_deliveries_reason_check" CHECK ("reason" in ('driver_without_account', 'driver_unreachable', 'whatsapp_window_closed', 'note_without_recipient_email', 'attachment_too_large_for_email', 'send_failed', 'client_without_email', 'whatsapp_number_not_found', 'whatsapp_disconnected', 'attachment_too_large_for_whatsapp'));--> statement-breakpoint
ALTER TABLE "occurrence_contractor_reply_deliveries" DROP CONSTRAINT "occurrence_contractor_reply_deliveries_address_check", ADD CONSTRAINT "occurrence_contractor_reply_deliveries_address_check" CHECK ("address" is null or ("target" in ('note_recipient_email', 'informed_email', 'client_boleto_emails') and char_length("address") between 1 and 254) or ("target" = 'client_boleto_whatsapp' and "address" ~ '^\+[1-9][0-9]{7,14}$'));--> statement-breakpoint
ALTER TABLE "occurrence_contractor_reply_events" DROP CONSTRAINT "occurrence_contractor_reply_events_reason_check", ADD CONSTRAINT "occurrence_contractor_reply_events_reason_check" CHECK ("reason" in ('no_accepted_attachment', 'multiple_attachments', 'document_not_confirmed', 'driver_without_account', 'driver_unreachable', 'whatsapp_window_closed', 'note_without_recipient_email', 'attachment_too_large_for_email', 'send_failed', 'client_without_email', 'whatsapp_number_not_found', 'whatsapp_disconnected', 'attachment_too_large_for_whatsapp', 'document_confirmed', 'document_without_text'));
